CREATE TABLE IF NOT EXISTS subcontracts(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,subcontract_code VARCHAR(30) NOT NULL,subcontract_number VARCHAR(100) NULL,project_id BIGINT UNSIGNED NOT NULL,vendor_id BIGINT UNSIGNED NOT NULL,pricing_method VARCHAR(20) NOT NULL,title VARCHAR(190) NOT NULL,description TEXT NULL,contract_date DATE NOT NULL,start_date DATE NULL,expected_end_date DATE NULL,contract_value DECIMAL(18,2) NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_subcontracts_code(subcontract_code),UNIQUE KEY uq_subcontracts_business_number(project_id,vendor_id,subcontract_number),KEY idx_subcontracts_filters(project_id,vendor_id,pricing_method,status,contract_date),CONSTRAINT fk_subcontracts_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT,CONSTRAINT fk_subcontracts_vendor FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE RESTRICT,CONSTRAINT chk_subcontracts_pricing CHECK(pricing_method IN('boq','lump_sum')),CONSTRAINT chk_subcontracts_status CHECK(status IN('draft','active','suspended','completed','cancelled')),CONSTRAINT chk_subcontracts_dates CHECK(start_date IS NULL OR expected_end_date IS NULL OR expected_end_date>=start_date),CONSTRAINT chk_subcontracts_value CHECK(contract_value IS NULL OR contract_value>=0),CONSTRAINT chk_subcontracts_lump_value CHECK(pricing_method<>'lump_sum' OR contract_value IS NOT NULL)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
